[ApiController]
[Route("api/leaderboard")]
public class LeaderboardController(LeaderboardService service) : ControllerBase
{
    [HttpGet]
    public Task<List<LeaderboardRow>> Get() => service.GetTopAsync(100);
}

public class LeaderboardService(AppDbContext db)
{
    public async Task<List<LeaderboardRow>> GetTopAsync(int count)
    {
        var players = await db.Players
            .OrderByDescending(p => p.Elo)
            .Take(count)
            .ToListAsync();

        var rows = new List<LeaderboardRow>();
        foreach (var player in players)
        {
            var wins = await db.Duels.CountAsync(d => d.WinnerId == player.Id);
            rows.Add(new LeaderboardRow(player.Nickname, player.Elo, wins));
        }
        return rows;
    }
}

public class AppDbContext(DbContextOptions<AppDbContext> options) : DbContext(options)
{
    public DbSet<Player> Players => Set<Player>();
    public DbSet<Duel> Duels => Set<Duel>();

    protected override void OnModelCreating(ModelBuilder model)
    {
        model.Entity<Player>().HasIndex(p => p.Elo);
        model.Entity<Duel>().HasIndex(d => d.WinnerId);
    }
}

import { pool } from '../db'

export async function getReport(req, res) {
  const client = await pool.connect()
  const { rows } = await client.query('SELECT * FROM reports WHERE id = $1', [req.params.id])

  if (rows.length === 0) {
    return res.status(404).json({ error: 'Report not found' })
  }

  client.release()
  res.json(rows[0])
}

import { pool } from '../db'

export async function getUser(req, res) {
  const { rows } = await pool.query('SELECT id, nickname FROM users WHERE id = $1', [req.params.id])
  if (rows.length === 0) return res.status(404).json({ error: 'User not found' })
  res.json(rows[0])
}

